def load() -> pd.DataFrame:
    import pandas as pd, glob

    patterns = [
        'data/astronomy/input/STORM-AI/warmup/v2/OMNI2/*.csv',
        'data/astronomy/input/STORM-AI/warmup/v2/GOES/*.csv',
        'data/astronomy/input/STORM-AI/warmup/v2/Sat_Density/*.csv',
    ]
    rows = []
    for pat in patterns:
        matches = sorted(glob.glob(pat))
        rows.append({'pattern': pat, 'n_matches': len(matches), 'first5': ', '.join(matches[:5])})
    return pd.DataFrame(rows)
